using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
using System.Text.Json;
namespace Society.Api;

public class FinanceWorker(IServiceScopeFactory factory,ILogger<FinanceWorker> log):BackgroundService {
 sealed class WorkerAccessor:IHttpContextAccessor{public HttpContext? HttpContext{get;set;}}
 public static (Access access,FinanceService service,CommunicationService comm) Context(AppDb db,Guid user,IConfiguration config){var accessor=new WorkerAccessor{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,user.ToString())],"FinanceWorker"))}};var a=new Access(db,accessor);var community=new CommunityService(db,a);return(a,new FinanceService(db,a,community),new CommunicationService(db,a,new MembershipService(db,a),community,config));}
 protected override async Task ExecuteAsync(CancellationToken stop){var sweep=DateTimeOffset.MinValue;while(!stop.IsCancellationRequested){var worked=false;try{using var scope=factory.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var config=scope.ServiceProvider.GetRequiredService<IConfiguration>();if(sweep<DateTimeOffset.UtcNow){await Schedule(db,config,stop);sweep=DateTimeOffset.UtcNow.AddSeconds(10);}worked=await Batch(db,config,scope.ServiceProvider,stop);}catch(Exception ex)when(!stop.IsCancellationRequested){log.LogWarning("Finance background pass failed: {Type}",ex.GetType().Name);}if(!worked)try{await Task.Delay(500,stop);}catch(OperationCanceledException){break;}}}
 static async Task<bool> Batch(AppDb db,IConfiguration config,IServiceProvider services,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var jobs=await db.Set<FinanceJob>().FromSqlRaw("SELECT * FROM \"FinanceJob\" WHERE \"State\"='Queued' ORDER BY \"At\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var job=jobs.FirstOrDefault();if(job==null){await tx.CommitAsync(ct);return false;}await FinanceService.Lock(db,job.TenantId);var cursor=Guid.TryParse(job.Cursor,out var parsed)?parsed:Guid.Empty;var (a,s,comm)=Context(db,job.AuthorId,config);try{
  if(job.Kind=="Assessment"){var plan=await db.Set<DuesPlan>().SingleAsync(p=>p.TenantId==job.TenantId&&p.EntityId==job.EntityId&&p.Id==job.PlanId,ct);await s.Require(job.TenantId,job.EntityId,job.UnitId,"finance.dues");if(plan.Target=="Member"){var ids=await db.Memberships.Where(m=>m.TenantId==job.TenantId&&m.Status=="Active"&&(plan.CategoryId==null||m.CategoryId==plan.CategoryId)&&a.InWorkspace(a.Visible(job.TenantId,"finance.dues"),job.TenantId,plan.UnitId).Select(u=>u.Id).Contains(m.ChapterId)&&db.Set<FinancialUnit>().Any(f=>f.EntityId==plan.EntityId&&f.UnitId==m.ChapterId)).Where(m=>job.Cursor==""||m.Id.CompareTo(cursor)>0).OrderBy(m=>m.Id).Select(m=>m.Id).Take(100).ToListAsync(ct);foreach(var id in ids){await s.Assess(plan,job.StartsOn,job.EndsOn,id,null);job.Cursor=id.ToString();job.Processed++;}if(ids.Count<100)job.State="Completed";}else{var ids=await db.Units.Where(u=>u.TenantId==job.TenantId&&u.Status=="Active"&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")&&a.InWorkspace(a.Visible(job.TenantId,"finance.dues"),job.TenantId,plan.UnitId).Select(u=>u.Id).Contains(u.Id)&&db.Set<FinancialUnit>().Any(f=>f.EntityId==plan.EntityId&&f.UnitId==u.Id)).Where(u=>job.Cursor==""||u.Id.CompareTo(cursor)>0).OrderBy(u=>u.Id).Select(u=>u.Id).Take(100).ToListAsync(ct);foreach(var id in ids){await s.Assess(plan,job.StartsOn,job.EndsOn,null,id);job.Cursor=id.ToString();job.Processed++;}if(ids.Count<100)job.State="Completed";}}
  else if(job.Kind=="BankImport"){await s.Require(job.TenantId,job.EntityId,job.UnitId,"finance.reconcile");var json=JsonSerializer.Deserialize<JsonElement>(job.Payload);var bankId=json.GetProperty("bankId").GetGuid();var bank=await db.Set<FinanceBank>().SingleAsync(b=>b.TenantId==job.TenantId&&b.EntityId==job.EntityId&&b.Id==bankId&&b.Active,ct);var rows=json.GetProperty("rows").Deserialize<BankRow[]>()!;var seen=new HashSet<string>();foreach(var row in rows.Skip(job.Processed).Take(100)){var hash=CommunityService.Hash(bankId+"|"+row.Date.ToString("O")+"|"+row.Reference+"|"+row.Amount.ToString(System.Globalization.CultureInfo.InvariantCulture));if(seen.Add(hash)&&!await db.Set<BankTransaction>().AnyAsync(b=>b.TenantId==job.TenantId&&b.BankId==bankId&&b.Fingerprint==hash,ct))db.Add(new BankTransaction{TenantId=job.TenantId,EntityId=job.EntityId,UnitId=job.UnitId,BankId=bankId,Reference=row.Reference,Date=row.Date,Amount=row.Amount,Currency=bank.Currency,Description=row.Description,Fingerprint=hash});job.Processed++;}if(job.Processed>=rows.Length)job.State="Completed";}
  else if(job.Kind=="Document"){var request=JsonSerializer.Deserialize<DocumentJob>(job.Payload)!;if(request.Kind=="Invoice")await s.Invoice(job.TenantId,request.Id);else{var receipt=await db.Set<FinanceReceipt>().SingleAsync(r=>r.Id==request.Id&&r.TenantId==job.TenantId);await FinanceEndpoints.ReceiptAccess(receipt,db,a,s);}var documents=services.GetRequiredService<FinanceDocuments>();job.DocumentId=await documents.Generate(job.TenantId,request.Kind,request.Id,ct);job.Processed=1;job.State="Completed";}
  else if(job.Kind=="Report"){await s.Require(job.TenantId,job.EntityId,job.UnitId,"finance.export");var payload=JsonSerializer.Deserialize<ReportJob>(job.Payload)!;var bytes=await FinanceExport.Build(job.TenantId,payload,db,a,s,services.GetRequiredService<FinanceDocuments>(),ct);var store=services.GetRequiredService<IObjectStore>();var file=new FinanceFile{TenantId=job.TenantId,EntityId=job.EntityId,UnitId=job.UnitId,ResourceId=job.Id,Kind="Report",Name=payload.Report+"."+payload.Format,ContentType=payload.Format=="pdf"?"application/pdf":payload.Format=="xlsx"?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"text/csv",Length=bytes.Length,AuthorId=job.AuthorId};await store.Put(job.TenantId,file.Id,bytes);db.Add(file);job.DocumentId=file.Id;job.State="Completed";job.Processed=1;}
  else throw new DomainException("Unknown finance job type");
  await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
 }catch(Exception ex)when(ex is DomainException or AccessDeniedException or DbUpdateException){await tx.RollbackAsync(ct);db.ChangeTracker.Clear();var failed=await db.Set<FinanceJob>().SingleAsync(j=>j.Id==job.Id,ct);failed.State="Failed";failed.Failed++;failed.Error=ex is DomainException d?d.Message:ex is AccessDeniedException?"Current finance authority is insufficient":"The batch failed a database integrity check; review its source records before retrying";await db.SaveChangesAsync(ct);}return true;}
 static async Task Schedule(AppDb db,IConfiguration config,CancellationToken ct){
 await db.Set<FinanceRefund>().Where(r=>r.Status=="Processing"&&r.ProcessingAt<DateTimeOffset.UtcNow.AddMinutes(-2)).ExecuteUpdateAsync(x=>x.SetProperty(r=>r.Status,"Unknown"),ct);await db.Set<PaymentIntent>().Where(i=>i.Status=="Creating"&&i.At<DateTimeOffset.UtcNow.AddMinutes(-2)).ExecuteUpdateAsync(x=>x.SetProperty(i=>i.Status,"Unknown"),ct);
 foreach(var plan in await db.Set<DuesPlan>().AsNoTracking().Where(p=>p.AutoBill&&p.Active&&p.EffectiveFrom<=FinanceService.Today&&(p.EffectiveTo==null||p.EffectiveTo>=FinanceService.Today)).OrderBy(p=>p.Id).Take(100).ToListAsync(ct)){
  if(!await MailWorker.Authority(db,plan.TenantId,plan.AuthorId,plan.UnitId,"finance.dues"))continue;
  var months=plan.Frequency switch{"Monthly"=>1,"Quarterly"=>3,"Half-yearly"=>6,"Annual"=>12,_=>0};var start=plan.EffectiveFrom;
  if(months>0){var elapsed=(FinanceService.Today.Year-start.Year)*12+FinanceService.Today.Month-start.Month;start=plan.EffectiveFrom.AddMonths(Math.Max(0,elapsed/months)*months);if(start>FinanceService.Today)start=start.AddMonths(-months);}
  var end=months==0?start:start.AddMonths(months).AddDays(-1);if(plan.EffectiveTo!=null&&end>plan.EffectiveTo)continue;
  var hasNew=plan.Target=="Member"?await db.Memberships.AnyAsync(m=>m.TenantId==plan.TenantId&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow)&&(plan.CategoryId==null||m.CategoryId==plan.CategoryId)&&db.Set<FinancialUnit>().Any(u=>u.EntityId==plan.EntityId&&u.UnitId==m.ChapterId)&&!db.Set<DuesAssessment>().Any(d=>d.PlanId==plan.Id&&d.MembershipId==m.Id&&(plan.Frequency=="Once"||d.StartsOn==start)),ct):await db.Set<FinancialUnit>().AnyAsync(u=>u.EntityId==plan.EntityId&&db.Units.Any(x=>x.Id==u.UnitId&&x.Status=="Active"&&db.Levels.Any(l=>l.Id==x.LevelId&&l.Kind=="Chapter"))&&!db.Set<DuesAssessment>().Any(d=>d.PlanId==plan.Id&&d.ChapterId==u.UnitId&&d.StartsOn==start),ct);
  var key="auto:"+plan.Id+":"+start;var job=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==plan.TenantId&&j.EntityId==plan.EntityId&&j.Key==key,ct);
  if(hasNew&&job==null)db.Add(new FinanceJob{TenantId=plan.TenantId,EntityId=plan.EntityId,UnitId=plan.UnitId,AuthorId=plan.AuthorId,PlanId=plan.Id,StartsOn=start,EndsOn=end,Key=key});else if(hasNew&&job?.State=="Completed"){job.State="Queued";job.Cursor="";}
 }
 await db.SaveChangesAsync(ct);await FinanceCommunication.Dispatch(db,config,ct);}

}
public record DocumentJob(string Kind,Guid Id);
public record ReportJob(Guid EntityId,Guid UnitId,string Report,string Format,DateOnly? From=null,DateOnly? To=null,Guid? MemberId=null,Guid? ChapterId=null,Guid? EventId=null);
